{
  "source_context": [
    {
      "section": "C1",
      "lyrics": [
        "何度でも",
        "何度でも叫ぶ",
        "この暗い夜の怪獣になっても",
        "ここに残しておきたいんだよ",
        "この秘密を"
      ]
    },
    {
      "section": "V1",
      "lyrics": [
        "だんだん食べる",
        "赤と青の星々",
        "未来から過去",
        "順々に食べる",
        "何十回も噛み潰し",
        "溶けたなら飲もう"
      ]
    },
    {
      "section": "C2",
      "lyrics": [
        "丘の上で星を見ると感じるこの寂しさも",
        "朝焼けで手が染まる頃にはもう忘れてるんだ",
        "この世界は好都合に未完成",
        "だから知りたいんだ",
        "でも怪獣みたいに遠く遠く叫んでも",
        "また消えてしまうんだ"
      ]
    }
  ],
  "section": "C2",
  "phrases": [
    {
      "id": "C2-01",
      "ja": "丘の上で星を見ると感じるこの寂しさも",
      "budget": {
