      },
      "pattern": [
        3,
        4
      ]
    },
    {
      "id": "C2-05",
      "ja": "でも怪獣みたいに遠く遠く叫んでも",
      "budget": {
        "min": 14,
        "max": 14
      },
      "pattern": [
        6,
        5,
        3
      ]
    },
    {
      "id": "C2-06",
      "ja": "また消えてしまうんだ",
      "budget": {
        "min": 8,
        "max": 8
      },
      "pattern": [
        5,
        3
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "C2-01",
          "zh": "站在山丘上仰望星空，这份寂寞也涌上心头"
        },
        {
          "id": "C2-02",
          "zh": "晨光染红双手的时候，早已把一切忘得干净"
        },
        {
          "id": "C2-03",
          "zh": "这世界恰好未完成"
        },
        {
          "id": "C2-04",
          "zh": "所以我才想要知道"
        },
        {
          "id": "C2-05",
          "zh": "可就算像怪兽一样远远地远远地呼喊"
        },
        {
          "id": "C2-06",
          "zh": "也还是会消失不见"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "C2-01",
          "zh": "站在山坡上 数着满天星 风穿过胸口 寂寞也一起涌来"
        },
        {
          "id": "C2-02",
          "zh": "朝霞染红手 天亮的时分 那些寂寞 早就 忘得很干净"
        },
        {
          "id": "C2-03",
          "zh": "这个世界 留着缝隙 还没做完"
        },
        {
          "id": "C2-04",
          "zh": "所以我 还想知道"
        },
        {
          "id": "C2-05",
          "zh": "我像怪兽一样 朝最远处喊 喊到哑"
        },
        {
          "id": "C2-06",
          "zh": "喊声散成风 又不见"
        }
      ]
    }
  ]
}

